#!/usr/bin/env python3
from pwn import *
import gdb

class TreeTracker(gdb.Command):
    def __init__(self):
        super(TreeTracker, self).__init__("track-tree", gdb.COMMAND_USER)
        self.nodes = {}

    def invoke(self, arg, from_tty):
        # Set breakpoint at check_value
        gdb.execute("break check_value")
        gdb.execute("run < input.txt")

        try:
            while True:
                # Get RSI register value (param_2)
                rsi = int(gdb.parse_and_eval("$rsi"))
                if rsi == 0:
                    break

                # Get comparison values
                lower_bound = int(gdb.parse_and_eval("*(unsigned char*)($rsi + 0x8)"))
                upper_bound = int(gdb.parse_and_eval("*(unsigned char*)($rsi + 0x9)"))
                left_child = int(gdb.parse_and_eval("*(void**)($rsi + 0x10)"))
                right_child = int(gdb.parse_and_eval("*(void**)($rsi + 0x18)"))

                # Store node information
                if rsi not in self.nodes:
                    self.nodes[rsi] = {
                        'bounds': (lower_bound, upper_bound),
                        'left': left_child,
                        'right': right_child
                    }

                # Continue execution
                gdb.execute("continue")

        except gdb.error:
            pass

        # Print tree structure
        print("\nBinary Tree Structure:")
        print("=====================")
        for addr, node in self.nodes.items():
            print(f"\nNode at 0x{addr:x}:")
            print(f"  Bounds: {node['bounds']}")
            print(f"  Left child: 0x{node['left']:x}")
            print(f"  Right child: 0x{node['right']:x}")

TreeTracker()

print("Tree tracker initialized. Create input file and run 'track-tree' command.")

