import gdb

class TreeTracer():
    def __init__(self):
        self.nodes = {}

    def track_node(self, address, comp_val, left_child, right_child):
        self.nodes[address] = {
            'comp_value': comp_val,
            'left_child': left_child,
            'right_child': right_child
        }

def get_memory_value(address, size=1):
    try:
        return int(gdb.selected_inferior().read_memory(address, size).tobytes().hex(), 16)
    except:
        return None

class CheckValueBreakpoint(gdb.Breakpoint):
    def __init__(self, tracer):
        super().__init__("*check_value", gdb.BP_BREAKPOINT)
        self.tracer = tracer

    def stop(self):
        try:
            rsi = int(gdb.parse_and_eval("$rsi"))
            if rsi == 0:
                return False

            comp_val = get_memory_value(rsi + 0x8)
            left_child = get_memory_value(rsi + 0x10, 8)
            right_child = get_memory_value(rsi + 0x18, 8)

            self.tracer.track_node(rsi, comp_val, left_child, right_child)
            print(f"Node at {hex(rsi)}: comp_val={hex(comp_val) if comp_val else 'None'}, left={hex(left_child) if left_child else 'None'}, right={hex(right_child) if right_child else 'None'}")

        except Exception as e:
            print(f"Error: {e}")
        return False

# Initialize debugging
gdb.execute("file /home/ctfplayer/ctf_files/rabbithole", to_string=True)
tracer = TreeTracer()
CheckValueBreakpoint(tracer)

print("Binary loaded")
print("\nStarting execution...")

# Run the program with input
gdb.execute("run < /home/ctfplayer/input.txt", to_string=True)

# Print tree structure
print("\nTree Structure:")
for addr, data in tracer.nodes.items():
    print(f"Node {hex(addr)}:")
    print(f"  Comparison value: {hex(data['comp_value']) if data['comp_value'] else 'None'}")
    print(f"  Left child: {hex(data['left_child']) if data['left_child'] else 'None'}")
    print(f"  Right child: {hex(data['right_child']) if data['right_child'] else 'None'}")

