import gdb

class TreeNode:
    def __init__(self, addr):
        self.addr = addr
        self.range_start = None
        self.range_end = None
        self.left = None
        self.right = None

def read_memory_byte(addr):
    try:
        return int(gdb.selected_inferior().read_memory(addr, 1)[0])
    except:
        return None

def read_memory_ptr(addr):
    try:
        # Read 8 bytes for 64-bit pointer
        data = gdb.selected_inferior().read_memory(addr, 8)
        # Convert to int using little endian
        return int.from_bytes(data, byteorder='little')
    except:
        return None

def track_node(rsi_val):
    if rsi_val == 0:
        return None

    node = TreeNode(rsi_val)

    # Read range values
    node.range_start = read_memory_byte(rsi_val + 8)
    node.range_end = read_memory_byte(rsi_val + 9)

    # Read child pointers
    left_ptr = read_memory_ptr(rsi_val + 0x10)
    right_ptr = read_memory_ptr(rsi_val + 0x18)

    print(f"Node at {hex(rsi_val)}:")
    print(f"  Range: {node.range_start} - {node.range_end}")
    print(f"  Left child: {hex(left_ptr) if left_ptr else 'None'}")
    print(f"  Right child: {hex(right_ptr) if right_ptr else 'None'}")
    print("-" * 40)

    return node

class TraceBreakpoint(gdb.Breakpoint):
    def __init__(self):
        super().__init__("*0x15637a", gdb.BP_BREAKPOINT)
        self.nodes = {}

    def stop(self):
        rsi = int(gdb.parse_and_eval("$rsi"))
        dil = int(gdb.parse_and_eval("$dil"))

        if rsi not in self.nodes:
            node = track_node(rsi)
            if node:
                self.nodes[rsi] = node
                print(f"Input value: {dil} (0x{dil:02x})")

        return False

print("GDB script loaded. Setting breakpoint...")
bp = TraceBreakpoint()
print("Breakpoint set. Running program...")

# Create input file
with open("input.txt", "w") as f:
    f.write("AAAA")

gdb.execute("file /home/ctfplayer/ctf_files/rabbithole")
gdb.execute("run < input.txt")

