import gdb

class Node:
    def __init__(self):
        self.value = None
        self.left = None
        self.right = None
        self.address = None

nodes = {}

def get_address_value(address, offset):
    try:
        value = gdb.parse_and_eval(f"*(int*)({address} + {offset})")
        return int(value)
    except:
        return None

def get_pointer_value(address, offset):
    try:
        value = gdb.parse_and_eval(f"*(void**)({address} + {offset})")
        return int(value)
    except:
        return None

def track_node():
    rsi = int(gdb.parse_and_eval("$rsi"))

    if rsi in nodes:
        return

    node = Node()
    node.address = rsi
    node.value = get_address_value(rsi, 0x8)
    node.left = get_pointer_value(rsi, 0x10)
    node.right = get_pointer_value(rsi, 0x18)

    nodes[rsi] = node
    print(f"Node at {hex(rsi)}:")
    print(f"  Value: {node.value}")
    print(f"  Left child: {hex(node.left) if node.left else 'None'}")
    print(f"  Right child: {hex(node.right) if node.right else 'None'}")
    print("---")

gdb.execute("file /home/ctfplayer/ctf_files/rabbithole")
