import gdb

# Store node information
class Node:
    def __init__(self, addr, value=None):
        self.address = addr
        self.value = value
        self.left = None
        self.right = None

nodes = {}

def read_memory(addr, size=1):
    try:
        return int(gdb.parse_and_eval(f"*(char*)({addr})"))
    except:
        return None

def read_pointer(addr):
    try:
        return int(gdb.parse_and_eval(f"*(void**)({addr})"))
    except:
        return None

class BinaryTreeTracer(gdb.Breakpoint):
    def stop(self):
        # Get RSI (node pointer)
        try:
            rsi = int(gdb.parse_and_eval("$rsi"))
            if rsi == 0:
                return False

            # Get comparison character from input
            rdi = int(gdb.parse_and_eval("$rdi"))
            input_char = chr(rdi) if 32 <= rdi <= 126 else hex(rdi)

            # Skip if we've already seen this node
            if rsi in nodes:
                print(f"Revisiting node {hex(rsi)} with input '{input_char}'")
                return False

            # Read node data
            value = read_memory(rsi + 0x8)
            left = read_pointer(rsi + 0x10)
            right = read_pointer(rsi + 0x18)

            # Create node
            node = Node(rsi, value)
            node.left = left
            node.right = right
            nodes[rsi] = node

            print(f"\nNode {hex(rsi)}:")
            print(f"  Input char: {input_char}")
            print(f"  Value: {value} (chr: {chr(value) if value and 32 <= value <= 126 else 'n/a'})")
            print(f"  Left child: {hex(left) if left else 'None'}")
            print(f"  Right child: {hex(right) if right else 'None'}")

            # Read potential null terminator
            null_term = read_memory(rsi)
            if null_term == 0:
                print("  This is a terminal node (null terminator)")

        except Exception as e:
            print(f"Error: {e}")

        return False

# Set up GDB
gdb.execute("file /home/ctfplayer/ctf_files/rabbithole")
print("Setting breakpoint at check_value...")
bp = BinaryTreeTracer("*check_value")
print("Running program...")
gdb.execute("run < /home/ctfplayer/input.txt")
